var MINOR_ROLES = ["Kid","Teen","Baby"];
function isAdultLenient(p) {
  return !!(p && p.name && p.name.length > 0 && !p.isMinor && !(p.age != null && p.age < 18) && !MINOR_ROLES.includes(p.role));
}
